// Package icons is the unified line-icon registry of ResearchOS (ui_plan.md §5).
//
// Every icon is a Lucide outline (https://lucide.dev, ISC License), drawn at
// 24 units with a 2-unit stroke and currentColor, so it inherits the text color
// and size of where it is used. Modules must take icons from this registry:
// introducing another icon style would break the visual system, and emoji are
// never functional icons.
//
// Sizes follow the design system: SizeDefault 16 for inline icons, SizeNav 18
// for navigation, SizeAction 20 for important actions.
package icons

import (
	"github.com/egoist/mygo/ui"
)

// Icon sizes of ui_plan.md §5.
const (
	// SizeDefault is the size of an inline icon.
	SizeDefault float32 = 16
	// SizeNav is the size of a navigation icon.
	SizeNav float32 = 18
	// SizeAction is the size of an important action's icon.
	SizeAction float32 = 20
)

// Icon is one icon of the registry. The SVG markup is embedded in this
// package and parsed once at init, so icons render offline with no fetch and
// no generated asset the build could miss.
type Icon struct {
	name string
	svg  *ui.SVG
}

func newIcon(name, markup string) *Icon {
	return &Icon{name: name, svg: ui.MustParseSVG([]byte(markup))}
}

// Name returns the Lucide name of the icon.
func (i *Icon) Name() string { return i.name }

// SVG returns the parsed icon.
func (i *Icon) SVG() *ui.SVG {
	if i == nil {
		return nil
	}
	return i.svg
}

